function locCategory(mat,koshu){
  const m=String(mat||""),k=String(koshu||"");
  if(/アルミ|A5052|A6063/.test(m))return "alumi";
  if(m.includes("チタン"))return "ti";
  if(!/^SUS/.test(m))return null; /* SS400等の鉄系はPDFに棚の定義がないため案内しない */
  if(k.includes("アングル"))return "angle";
  if(k.includes("角パイプ"))return "kaku";
  if(k.includes("サニタリー"))return "sani";
  if(k.includes("化粧")||k.includes("BA管"))return "kesho";
  if(k.includes("丸パイプ"))return "maru";
  if(k.includes("チャンネル"))return "chan";
  return null; /* フラットバー等も棚の定義がないため案内しない */
}
/* 規格を比較用に正規化（Φ8.0 → "8"、50×50 → "50*50"） */
function sizeKey(s){
  return normSpec(s).split("*").map(x=>{const v=x.trim(),n=Number(v);return v!==""&&isFinite(n)?String(n):v;}).join("*");
}
/* 置き場所の判定。該当する棚が無い・寸法が棚の表に無いときは null（＝今の場所のまま・案内なし） */
function suggestLoc(rec){
  const cat=locCategory(rec.mat,rec.koshu);
  if(!cat)return null;
  const fin=String(rec.fin||"").trim();
  const spec=sizeKey(rec.spec);
  const len=Number(rec.len)||0;
  if(!spec||!(len>0))return null;
  const finOk=g=>{
    if(!g.fin)return true;
    if(g.fin.includes(fin))return true;
    /* 片#400・両#400 は #400 の棚として扱う */
    if(fin.includes("#400")&&g.fin.some(f=>f.includes("#400")))return true;
    return false;
  };
  const cands=[];
  LOC_GUIDE.forEach(g=>{
    if(g.cat!==cat||!finOk(g))return;
    let specific=false;
    if(g.sizes){
      const hit=typeof g.sizes==="function"?g.sizes(spec):g.sizes.some(x=>sizeKey(x)===spec);
      if(!hit)return;
      specific=true;
    }
    const inRange=len>=g.min&&len<=g.max;
    cands.push({g,dist:inRange?0:(len<g.min?g.min-len:len-g.max),width:g.max-g.min,specific});
  });
  if(!cands.length)return null;
  /* 今の棚が条件（仕上げ・寸法・長さ）を満たしていれば動かさない */
  const cur=String(rec.loc||"").trim();
  if(cands.some(c=>c.g.loc===cur&&c.dist===0))return cur;
  /* 長さが近い棚 → 寸法指定のある棚 → 長さの幅が狭い棚 の順 */
  cands.sort((a,b)=>(a.dist-b.dist)||(b.specific-a.specific)||(a.width-b.width));
  return cands[0].g.loc;
}

/* ===================== 計算エンジン（Excel数式と同一） ===================== */
function normSpec(s){return String(s==null?"":s).replace(/[Φφ]/g,"").replace(/[×Xx]/g,"*").trim();}
function dims(spec){const n=normSpec(spec),p=n.split("*");const d1=parseFloat(p[0]);const d2=p.length>1?parseFloat(p[1]):NaN;return{d1:isFinite(d1)?d1:0,d2:isFinite(d2)?d2:0};}
function density(mat){return DENSITY[mat]!=null?DENSITY[mat]:(String(mat).startsWith("SUS")?7.93:7.85);}

/* サニタリーパイプは呼び径(1S/1.5S/2S…)で外径と肉厚が決まる（JIS G3447）。
 * 外径→肉厚の対応表。登録フォームで板厚が未選択のとき自動補完する */
const SANITARY_T={"25.4":1.2,"31.8":1.2,"32":1.2,"38.1":1.2,"50":1.5,"50.8":1.5,"63.5":2,"76.3":2,"89.1":2,"101.6":2,"114.3":3,"139.8":3};
function sanitaryThk(spec){const{d1}=dims(spec);if(!d1)return null;const t=SANITARY_T[String(d1)];return t!=null?t:null;}
function hookSanitaryThk(koshuSel,specEl,thkSel){
  const fill=()=>{
    if(!String($(koshuSel).value).includes("サニタリー"))return;
    const cur=$(thkSel).value;
    if(cur!==""&&Number(cur)!==0)return; /* 手で選んだ値は上書きしない */
    const t=sanitaryThk($(specEl).value);
    if(t!=null){$(thkSel).value=String(t);$(thkSel).dispatchEvent(new Event("change",{bubbles:true}));}
  };
  $(specEl).addEventListener("input",fill);
  $(specEl).addEventListener("change",fill);
  $(koshuSel).addEventListener("change",fill);
}
function sectionArea(mat,koshu,thk,spec){
  const{d1,d2}=dims(spec);const t=parseFloat(thk)||0;
  const fm=AREA_FORMULAS[KOSHU_FORMULA[koshu]];
  return fm?fm.calc(d1,d2,t):null;
}
function round(v,d){const f=Math.pow(10,d);return Math.round((v+Number.EPSILON)*f)/f;}
function weightKg(mat,koshu,thk,spec,len){const a=sectionArea(mat,koshu,thk,spec);if(a==null||!isFinite(a))return null;const L=parseFloat(len)||0;return round(a*L*density(mat)/1e6,3);}
function unitPrice(mat,koshu,fin){
  let rows;
  if(mat==="SS400"||mat==="A6063")rows=PRICE.filter(p=>p.mat===mat&&p.koshu===koshu);
  else{
    rows=PRICE.filter(p=>p.mat===mat&&p.koshu===koshu&&p.fin===fin);
    /* 仕上げ完全一致の行が無いときだけ「仕上げ不問(null)」行で代用。
     * 既存マスタにSUS系のnull行は無いため、従来の挙動（完全一致・合算）は変わらない。
     * CIPS発注実績から作る平均単価行（fin=null）を新しい組み合わせに使うための追加（2026-09） */
    if(!rows.length)rows=PRICE.filter(p=>p.mat===mat&&p.koshu===koshu&&p.fin==null);
  }
  if(!rows.length)return null;
  return rows.reduce((s,p)=>s+p.price,0);
}
function compute(r){
  const area=sectionArea(r.mat,r.koshu,r.thk,r.spec);
  const w=weightKg(r.mat,r.koshu,r.thk,r.spec,r.len);
  const u=unitPrice(r.mat,r.koshu,r.fin);
  const cost=(w!=null&&u!=null)?round(w*u,0):null;
  return{area:area!=null&&isFinite(area)?area:null,weight:w,unit:u,cost};
}

