function locOptions(){const s=[...new Set(records.map(r=>r.loc).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"ja"));return s.length?s:LOCATIONS;}

/* ── 選択肢の動的生成：マスタ＋在庫の実データにある文言を合算 ──
 * 新規登録・検索・持ち出しの選択肢が、実在庫に出てくる値を自動で含むようにする */
function uniqVals(arr){return [...new Set(arr.filter(v=>v!==""&&v!=null))];}
function matOptions(){return uniqVals([...MATERIALS,...records.map(r=>r.mat)]);}
function koshuOptions(mat){
  let base=(mat&&KOSHU_BY_MAT[mat])?KOSHU_BY_MAT[mat]:[];
  /* 規格表がある材質は、その材質で実在する鋼種だけ（例：アルミにサニタリーパイプは出さない） */
  if(mat&&typeof STEEL_CATALOG!=="undefined"){
    const inCat=Object.keys(STEEL_CATALOG).filter(k=>k.startsWith(mat+"|")).map(k=>k.slice(mat.length+1));
    if(inCat.length)base=base.filter(k=>inCat.includes(k)).concat(inCat.filter(k=>!base.includes(k)));
  }
  return uniqVals([...base,...records.filter(r=>!mat||r.mat===mat).map(r=>r.koshu)]);
}
/* 規格表（STEEL_CATALOG）を引く。無い組み合わせ・受注生産（special＝寸法表なし）は null（＝従来どおり絞らない） */
function catEntry(mat,koshu){const e=mat&&koshu&&STEEL_CATALOG[mat+"|"+koshu];return (e&&!e.special)?e:null;}
function catEntries(mat){return Object.keys(STEEL_CATALOG).filter(k=>k.startsWith(mat+"|")).map(k=>STEEL_CATALOG[k]).filter(e=>!e.special);}
function catThks(e){const s=[];Object.values(e.sizes||{}).forEach(a=>s.push(...a));Object.values(e.finThk||{}).forEach(a=>s.push(...a));return s;}
const noThk=thk=>thk===""||thk==null;
const thkEq=(a,b)=>Number(a)===Number(b);
/* 規格の並び順：寸法の数字の小さい順（Φ27.2 → 27.2、50*25 → 50,25） */
function specSort(a,b){
  const pa=normSpec(a).split("*").map(parseFloat),pb=normSpec(b).split("*").map(parseFloat);
  for(let i=0;i<Math.max(pa.length,pb.length);i++){const x=pa[i]||0,y=pb[i]||0;if(x!==y)return x-y;}
  return String(a).localeCompare(String(b));
}
/* 板厚の候補：材質（と鋼種）を選んでいれば、規格表と在庫にある板厚だけ */
function thkOptions(mat,koshu){
  const recs=records.filter(r=>(!mat||r.mat===mat)&&(!koshu||r.koshu===koshu)).map(r=>r.thk);
  let base=THICKNESS;
  if(mat&&!(koshu&&!catEntry(mat,koshu))){ /* 規格表に無い鋼種（受注生産など）は従来どおり全部＋在庫の値 */
    const es=koshu?[catEntry(mat,koshu)]:catEntries(mat);
    base=[].concat(...es.map(catThks));
    if(!base.length&&!recs.length)base=THICKNESS; /* 規格表にも在庫にも無い組み合わせは従来どおり全部 */
  }
  return uniqVals([...base,...recs]).map(Number).filter(n=>isFinite(n))
    .filter((n,i,a)=>a.indexOf(n)===i).sort((a,b)=>a-b);
}
/* 材料規格の候補：規格表（その板厚で作られている寸法）＋マスタ設定の候補＋在庫にある規格 */
function specOptions(koshu,mat,thk){
  const e=catEntry(mat,koshu);
  const cat=e?Object.keys(e.sizes||{}).filter(s=>noThk(thk)||e.sizes[s].some(t=>thkEq(t,thk))):[];
  const useMaster=!e||KIKAKU_CUSTOM; /* 規格表がある組み合わせでは、既定の候補（Excel由来の数件）は出さない */
  const base=!useMaster?[]:(koshu&&KIKAKU_BY_KOSHU[koshu])?KIKAKU_BY_KOSHU[koshu]:(koshu?[]:[].concat(...Object.values(KIKAKU_BY_KOSHU)));
  const recs=records.filter(r=>(!koshu||r.koshu===koshu)&&(!mat||r.mat===mat)&&(noThk(thk)||thkEq(r.thk,thk))).map(r=>r.spec);
  const all=uniqVals([...cat,...base,...recs]);
  return (mat||koshu)?all.sort(specSort):all;
}
/* 表面仕上げの候補：規格表でその材質・鋼種（・板厚・規格）にある仕上げ＋在庫にある仕上げだけ。
 * 規格表に寸法ごとの仕上げ（byFin）があれば、入力された規格でさらに絞る */
function finOptions(mat,koshu,thk,spec){
  const e=catEntry(mat,koshu);
  const sp=spec?normSpecKey(spec):"";
  let base;
  if(e){
    const bf=sp&&e.byFin?Object.entries(e.byFin).find(([s])=>normSpecKey(s)===sp):null;
    if(bf)base=Object.keys(bf[1]).filter(f=>noThk(thk)||bf[1][f].some(t=>thkEq(t,thk)));
    else base=(e.fin||[]).filter(f=>{const ts=e.finThk&&e.finThk[f];return noThk(thk)||!ts||!ts.length||ts.some(t=>thkEq(t,thk));});
    base=(e.fin||[]).filter(f=>base.includes(f)); /* 並び順は規格表の fin の順 */
  }
  else if(mat&&!koshu&&catEntries(mat).length)base=uniqVals([].concat(...catEntries(mat).map(x=>x.fin||[])));
  else base=(mat&&koshu)?finishOptions(mat,koshu):FINISH_ALL;
  const recs=records.filter(r=>(!mat||r.mat===mat)&&(!koshu||r.koshu===koshu)&&(noThk(thk)||thkEq(r.thk,thk))&&(!sp||normSpecKey(r.spec)===sp)).map(r=>r.fin);
  return uniqVals([...base,...recs]);
}
/* 規格の比較用キー（Φ34.0 と Φ34、50×50 と 50*50 を同じとみなす） */
function normSpecKey(s){return normSpec(s).split("*").map(x=>{const v=x.trim(),n=Number(v);return v!==""&&isFinite(n)?String(n):v;}).join("*");}
/* 選択肢を差し替える（内容が変わったときだけ。選択中の値は維持） */
function refillSelect(sel,opts,blank){
  const key=opts.join("|");
  if(sel.dataset.opts===key)return;
  const cur=sel.value;fillSelect(sel,opts,blank);sel.dataset.opts=key;
  if(opts.map(String).includes(cur))sel.value=cur;
}
/* 名前の選択肢：名簿マスタ（マスタ設定で編集）。名簿が空のときだけ
 * 持ち出し/鍵の履歴に出てくる名前で代用（システム操作名は候補に入れない） */
function personOptions(){
  if(STAFF.length)return uniqVals([...STAFF]);
  return uniqVals(history.filter(x=>x.type==="checkout"||x.type==="keyout"||x.type==="keyin").map(x=>x.person));
}
/* 名前ピッカー：選択肢から選ぶ。前回の名前（端末に記憶）を自動選択。「直接入力」も可 */
function setupPersonPicker(selSel,inpSel){
  const sel=$(selSel),inp=$(inpSel);if(!sel||!inp)return;
  const opts=personOptions();
  let stored="";try{stored=(localStorage.getItem(PERSON_KEY)||"").trim();}catch(e){}
  sel.innerHTML="";
  const blank=document.createElement("option");blank.value="";blank.textContent=t("名前を選んでください");sel.appendChild(blank);
  opts.forEach(o=>{const e=document.createElement("option");e.value=o;e.textContent=o;sel.appendChild(e);});
  const free=document.createElement("option");free.value="__free";free.textContent=t("（名前を直接入力）");sel.appendChild(free);
  if(stored&&opts.includes(stored))sel.value=stored;
  else if(stored){sel.value="__free";inp.value=stored;}
  else inp.value="";
  const sync=()=>{inp.style.display=sel.value==="__free"?"block":"none";if(sel.value==="__free")setTimeout(()=>inp.focus(),50);};
  sel.onchange=sync;sync();
}
function pickerValue(selSel,inpSel){const sel=$(selSel);return sel.value==="__free"?$(inpSel).value.trim():sel.value.trim();}

/* 検索フィルタの選択肢を実データに追従させる */
function refreshSearchFilters(){
  refillSelect($("#f_mat"),matOptions(),"すべての材質");
  const m=$("#f_mat").value;
  if(m){refillSelect($("#f_koshu"),koshuOptions(m),"すべての鋼種");$("#f_koshu").disabled=false;}
  refreshSearchThkFin();
}
/* 検索の板厚・仕上げ：材質（鋼種・板厚）を選んだら、在庫に実際にあるものだけ */
function refreshSearchThkFin(){
  const m=$("#f_mat").value,k=$("#f_koshu").value;
  const recs=records.filter(r=>(!m||r.mat===m)&&(!k||r.koshu===k));
  const thks=(m||k)?uniqVals(recs.map(r=>r.thk)).map(Number).filter(n=>isFinite(n)).filter((n,i,a)=>a.indexOf(n)===i).sort((a,b)=>a-b):thkOptions();
  refillSelect($("#f_thk"),thks.map(String),"すべて");
  const th=$("#f_thk").value;
  const fins=(m||k||th!=="")?uniqVals(recs.filter(r=>th===""||thkEq(r.thk,th)).map(r=>r.fin)):finOptions("","");
  refillSelect($("#f_fin"),fins,"すべて");
}
function finishOptions(mat,koshu){const k=mat+"|"+koshu;if(FINISH_BY_MAT_KOSHU[k]&&FINISH_BY_MAT_KOSHU[k].length)return FINISH_BY_MAT_KOSHU[k];return FINISH_ALL;}
function toast(msg,ms){const t=$("#toast");$("#toastMsg").textContent=msg;t.classList.add("show");clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove("show"),ms||2200);}

/* ===================== 元に戻す（記録の直後の取り消し） =====================
 * 持ち出し・残材登録・鍵・在庫の登録/編集/削除の直後に「元に戻す」バーを15秒出す。
 * 押すとサーバーがその記録を取り消す（記録から5分以内は誰でも可。全部持ち出しは同じ番号で在庫が復活）。
 * 単体版（オフライン）では出さず、従来どおりのお知らせだけ */
const UNDO_SHOW_SEC=15;
let undoState=null;
function offerUndo(hid,msg){
  if(MODE!=="server"||!hid){toast(msg);return;}
  hideUndo();
  let left=UNDO_SHOW_SEC;
  $("#undoMsg").textContent=msg;
  $("#undoCount").textContent=left+t("秒");
  undoState={hid,timer:setInterval(()=>{left--;$("#undoCount").textContent=left+t("秒");if(left<=0)hideUndo();},1000)};
  $("#toast").classList.remove("show");
  $("#undoBar").classList.add("show");document.body.classList.add("undo-on");
}
function hideUndo(){
  if(undoState)clearInterval(undoState.timer);
  undoState=null;
  $("#undoBar").classList.remove("show");document.body.classList.remove("undo-on");
}
/* 取り消しの実行（直後のバー・作業ログの両方から使う）。admin=true なら管理者パスコードを付けて送る */
async function runUndo(hid,admin){
  let person="";try{person=(localStorage.getItem(PERSON_KEY)||"").trim();}catch(e){}
  const body={id:hid,person:person||(admin?"管理者":"")};
  if(admin)body.pin=ADMIN_PIN;
  await apiSend("POST","/api/undo",body);
  closeLocGuide();
  try{await refresh();}catch(e){} /* 取り消しは済んでいる。画面更新は次のポーリングでも回復 */
  await loadHistory();
}
async function undoFromBar(){
  if(!undoState)return;
  const hid=undoState.hid;hideUndo();
  try{await runUndo(hid,false);toast(t("元に戻しました"));}
  catch(e){toast(t(e.message),6000);}
}

/* 確認画面（はい／戻る）。Promise<boolean> を返す */
function askConfirm(o){
  return new Promise(resolve=>{
    const ov=$("#confirmOverlay");
    $("#confirmTitle").textContent=o.title||"";
    $("#confirmBody").innerHTML=o.bodyHtml||"";
    $("#confirmYes").textContent=o.yes||t("はい");
    $("#confirmNo").textContent=o.no||t("戻る");
    const done=v=>{ov.classList.remove("show");$("#confirmYes").onclick=null;$("#confirmNo").onclick=null;ov.onclick=null;resolve(v);};
    $("#confirmYes").onclick=()=>done(true);
    $("#confirmNo").onclick=()=>done(false);
    ov.onclick=e=>{if(e.target===ov)done(false);};
    ov.classList.add("show");
    setTimeout(()=>$("#confirmNo").focus(),50);
  });
}

